const existing = JSON.parse(fs.readFileSync(eventsPath, 'utf8'));

const newEvents = [
  { "id": "nov-sarajevo-assassinio", "title": "L'Assassinio di Sarajevo — La Scintilla della Grande Guerra", "year": 1914, "lat": 43.8584, "lng": 18.4312, "category": "storia", "description": "Il 28 giugno 1914 l'arciduca Francesco Ferdinando, erede al trono austro-ungarico, viene assassinato a Sarajevo da Gavrilo Princip, nazionalista serbo-bosniaco. L'attentato innesca una catena di ultimatum e mobilitazioni che in sei settimane coinvolgono tutte le grandi potenze europee. Sarajevo diventa il simbolo del momento in cui il sistema delle alleanze trasforma un crimine politico in una guerra mondiale.", "wikipediaSlug": "Assassination_of_Archduke_Franz_Ferdinand", "isCosmic": false },
  { "id": "nov-germania-invade-belgio", "title": "La Violazione della Neutralità Belga", "year": 1914, "lat": 50.8503, "lng": 4.3517, "category": "storia", "description": "Il 4 agosto 1914 la Germania invade il Belgio attuando il Piano Schlieffen: aggirare le difese francesi attraverso il Belgio per conquistare Parigi in sei settimane. L'invasione porta la Gran Bretagna in guerra. Bruxelles cade il 20 agosto; i tedeschi fucilano civili a Lovanio e bruciano la biblioteca universitaria medievale. La 'piccola Belgio' che resiste diventa simbolo di coraggio contro l'aggressione imperialista.", "wikipediaSlug": "German_invasion_of_Belgium_(1914)", "isCosmic": false },
  { "id": "nov-prima-marna", "title": "La Prima Battaglia della Marna — Parigi Salvata", "year": 1914, "lat": 49.0500, "lng": 3.7000, "category": "storia", "description": "Dal 5 al 12 settembre 1914 le armate francesi e il BEF britannico fermano l'avanzata tedesca sul fiume Marna a est di Parigi. I taxi di Parigi portano riserve al fronte. Il fallimento del Piano Schlieffen condanna la Germania alla guerra su due fronti. Inizia la 'corsa al mare': entrambi gli eserciti si affiancano verso nord cercando di aggirare il fianco avversario, fino a che il fronte si stabilizza in centinaia di chilometri di trincee.", "wikipediaSlug": "First_Battle_of_the_Marne", "isCosmic": false },
  { "id": "nov-natale-trincea", "title": "La Tregua di Natale 1914 — Soldati Nemici Giocano a Calcio", "year": 1914, "lat": 50.6326, "lng": 2.9000, "category": "storia", "description": "La notte del 24 dicembre 1914 lungo il fronte occidentale soldati tedeschi e britannici smettono spontaneamente di combattere: cantano canzoni natalizie, si scambiano sigarette e cibo nella terra di nessuno, e in alcuni settori giocano a calcio. La tregua non è ordinata da nessun ufficiale — è un atto spontaneo di umanità in mezzo all'orrore. Non si ripeterà mai più con la stessa intensità e diventa leggenda della Grande Guerra.", "wikipediaSlug": "Christmas_truce", "isCosmic": false },
  { "id": "nov-tannenberg-fronte-est", "title": "La Battaglia di Tannenberg — Distruzione dell'Esercito Russo", "year": 1914, "lat": 53.4800, "lng": 20.2800, "category": "storia", "description": "Dal 26 al 30 agosto 1914 l'esercito tedesco circonda e distrugge la Seconda Armata russa in Prussia Orientale: 92.000 prigionieri, 78.000 morti. Hindenburg e Ludendorff diventano eroi nazionali. Il generale Samsonov si suicida. La vittoria di Tannenberg salva la Prussia Orientale e lancia Hindenburg al vertice dell'esercito tedesco, destinato a diventare presidente della Repubblica di Weimar nel 1925.", "wikipediaSlug": "Battle_of_Tannenberg_(1914)", "isCosmic": false },
  { "id": "nov-guerra-trincea-inizia", "title": "La Guerra di Trincea — 700 Chilometri di Fango", "year": 1914, "lat": 50.0000, "lng": 3.0000, "category": "storia", "description": "Nell'autunno 1914 entrambi gli eserciti si interrano: nascono le trincee del fronte occidentale, 700 km di fossati dal Canale della Manica alla Svizzera. Vita nella trincea: fango, ratti, pidocchi, proiettili, gas, cadaveri. Per quattro anni il fronte si sposta di pochi chilometri in cambio di centinaia di migliaia di morti. La trincea diventa il simbolo della Grande Guerra e della follia della guerra industriale.", "wikipediaSlug": "Trench_warfare", "isCosmic": false },
  { "id": "nov-genocidio-armeni", "title": "Il Genocidio Armeno — Il Primo Genocidio del XX Secolo", "year": 1915, "lat": 39.9334, "lng": 32.8597, "category": "storia", "description": "Dal 1915 al 1923 il governo ottomano deporta sistematicamente e massacra la popolazione armena dell'Anatolia: tra 600.000 e 1,5 milioni di morti. Le marce della morte nel deserto siriano, i massacri di massa, le annegazioni nel Mar Nero. Il termine 'genocidio' viene coniato da Rafael Lemkin nel 1944 richiamandosi agli armeni. La Turchia ancora oggi non riconosce ufficialmente il genocidio — fonte di tensione diplomatica.", "wikipediaSlug": "Armenian_genocide", "isCosmic": false },
  { "id": "nov-gallipoli-sbarco", "title": "Gallipoli — Il Fallimento degli Alleati ai Dardanelli", "year": 1915, "lat": 40.2637, "lng": 26.3228, "category": "storia", "description": "Il 25 aprile 1915 truppe britanniche, australiane, neozelandesi e francesi sbarcano nella penisola di Gallipoli per aprire un fronte meridionale e raggiungere Costantinopoli. L'ANZAC Cove diventa simbolo del sacrificio coloniale. L'operazione fallisce: il 19 dicembre 1915 gli Alleati si ritirano dopo 250.000 vittime. Il 25 aprile è ancora oggi festa nazionale in Australia e Nuova Zelanda — l'ANZAC Day.", "wikipediaSlug": "Gallipoli_campaign", "isCosmic": false },
  { "id": "nov-lusitania-affondamento", "title": "Il Lusitania — La Guerra Sottomarina Spinge gli USA", "year": 1915, "lat": 51.4000, "lng": -8.5333, "category": "storia", "description": "Il 7 maggio 1915 il transatlantico britannico Lusitania viene affondato da un sottomarino tedesco al largo dell'Irlanda: 1.198 morti, di cui 128 americani. L'indignazione negli USA è enorme. La Germania sospende temporaneamente la guerra sottomarina illimitata, ma nel 1917 la riprende — uno dei motivi che portano gli USA in guerra. 'Ricordate il Lusitania' diventa slogan della propaganda alleata.", "wikipediaSlug": "RMS_Lusitania", "isCosmic": false },
  { "id": "nov-gas-ypres-seconda", "title": "Il Gas Cloro ad Ypres — La Guerra Chimica Inizia", "year": 1915, "lat": 50.8503, "lng": 2.8637, "category": "storia", "description": "Il 22 aprile 1915 i tedeschi rilasciano 168 tonnellate di gas cloro contro le linee alleate nella Seconda Battaglia di Ypres — primo grande uso di armi chimiche nella storia. Il gas uccide migliaia di soldati o li lascia con polmoni devastati. Fritz Haber, il chimico tedesco che guida lo sviluppo del gas, riceve il Nobel per la Chimica nel 1918 per la sintesi dell'ammoniaca — grande controversia morale.", "wikipediaSlug": "Second_Battle_of_Ypres", "isCosmic": false },
  { "id": "nov-italia-entra-guerra", "title": "L'Italia Entra in Guerra — Il Patto di Londra", "year": 1915, "lat": 41.9028, "lng": 12.4964, "category": "storia", "description": "Il 23 maggio 1915 l'Italia dichiara guerra all'Austria-Ungheria, uscendo dalla neutralità e tradendo la Triplice Alleanza. Il Patto di Londra promette all'Italia Trento, Trieste, l'Istria e la Dalmazia. Il fronte italiano corre lungo l'Isonzo e sul Carso: undici battaglie dell'Isonzo in due anni, centinaia di migliaia di morti per pochi chilometri. La guerra si chiuderà con la 'vittoria mutilata' che alimenterà il fascismo.", "wikipediaSlug": "Kingdom_of_Italy_in_World_War_I", "isCosmic": false },
  { "id": "nov-verdun-battaglia", "title": "Verdun — Il Tritacarne della Grande Guerra", "year": 1916, "lat": 49.1600, "lng": 5.3833, "category": "storia", "description": "Dal 21 febbraio al 18 dicembre 1916 la Battaglia di Verdun è la più lunga della Prima Guerra Mondiale: 300.000 morti, 400.000 feriti. Il generale Falkenhayn vuole 'dissanguare' l'esercito francese. Fort Douaumont cade e viene riconquistato. Il fango di Verdun è ancora oggi pieno di resti umani e proiettili inesplosi — zona rossa inaccessibile. La battaglia diventa simbolo dell'assurdità della guerra di trincea.", "wikipediaSlug": "Battle_of_Verdun", "isCosmic": false },
  { "id": "nov-jutland-navale", "title": "La Battaglia dello Jutland — La Grande Flotta contro la Flotta d'Alto Mare", "year": 1916, "lat": 56.5000, "lng": 5.5000, "category": "storia", "description": "Il 31 maggio 1916 nel Mar del Nord si scontrano le due più grandi flotte da guerra mai costruite: la Grand Fleet britannica (150 navi) contro la Hochseeflotte tedesca (99 navi). Risultato inconcludente: i britannici perdono più navi ma i tedeschi non escono più in mare aperto. La Germania non romperà mai il blocco navale britannico — che alla fine la strangola economicamente.", "wikipediaSlug": "Battle_of_Jutland", "isCosmic": false },
  { "id": "nov-somme-battaglia", "title": "La Battaglia della Somme — 57.000 Morti nel Primo Giorno", "year": 1916, "lat": 49.9000, "lng": 2.7000, "category": "storia", "description": "Il 1° luglio 1916 inizia la Battaglia della Somme con l'attacco britannico: 57.000 caduti nel solo primo giorno — il giorno più sanguinoso della storia militare britannica. Il 15 settembre 1916 compaiono per la prima volta i carri armati britannici (Mark I). Dopo 141 giorni e 1,2 milioni di vittime totali, il fronte avanza di 12 km. Simbolo dell'inutile massacro della Grande Guerra.", "wikipediaSlug": "Battle_of_the_Somme", "isCosmic": false },
  { "id": "nov-brusilov-offensiva", "title": "L'Offensiva Brusilov — Il Capolavoro Tattico Russo", "year": 1916, "lat": 49.0000, "lng": 26.0000, "category": "storia", "description": "Dal giugno all'ottobre 1916 il generale Brusilov lancia la più riuscita offensiva alleata della Grande Guerra: attacchi coordinati su un fronte di 480 km sfondano le linee austro-ungariche in Ucraina. Un milione di prigionieri, 400.000 austriaci morti. L'offensiva è ancora studiata nelle accademie militari come modello di attacco coordinato ma esaurisce le ultime riserve della Russia zarista.", "wikipediaSlug": "Brusilov_offensive", "isCosmic": false },
  { "id": "nov-pasqua-dublino", "title": "L'Insurrezione di Pasqua — Il Grido dell'Irlanda", "year": 1916, "lat": 53.3498, "lng": -6.2603, "category": "storia", "description": "Il 24 aprile 1916 (Lunedì di Pasqua) i repubblicani irlandesi occupano l'Ufficio Postale Generale di Dublino e proclamano la Repubblica Irlandese. L'insurrezione viene schiacciata in una settimana; i 16 leader vengono fucilati — tra cui Patrick Pearse e James Connolly. Le esecuzioni trasformano i ribelli in martiri e danno impulso decisivo all'indipendentismo che porterà alla guerra d'indipendenza irlandese.", "wikipediaSlug": "Easter_Rising", "isCosmic": false },
  { "id": "nov-rivoluzione-febbraio", "title": "La Rivoluzione di Febbraio — Lo Zar Abdica", "year": 1917, "lat": 59.9311, "lng": 30.3609, "category": "storia", "description": "Nel marzo 1917 (febbraio giuliano) le lavoratrici di Pietrogrado scioperano per il pane causato dalla carestia di guerra. Le truppe si uniscono ai manifestanti. Lo Zar Nicola II abdica il 15 marzo: 300 anni di dinastia Romanov finiscono in pochi giorni. Si forma il Governo Provvisorio di Kerensky in parallelo ai Soviet operai. La Russia continua la guerra — errore fatale che apre la strada a Lenin.", "wikipediaSlug": "February_Revolution", "isCosmic": false },
  { "id": "nov-usa-entra-guerra", "title": "Gli Stati Uniti Entrano in Guerra — La Grande Democrazia si Sveglia", "year": 1917, "lat": 38.8951, "lng": -77.0364, "category": "storia", "description": "Il 6 aprile 1917 il Congresso degli Stati Uniti dichiara guerra alla Germania. Due motivi: la ripresa della guerra sottomarina illimitata tedesca e il Telegramma Zimmermann (proposta tedesca al Messico di attaccare gli USA). L'AEF (American Expeditionary Forces) di Pershing sbarca in Francia: 2 milioni di soldati americani cambieranno gli equilibri nel 1918 e decideranno l'esito della guerra.", "wikipediaSlug": "United_States_declaration_of_war_on_Germany_(1917)", "isCosmic": false },
  { "id": "nov-zimmermann-telegramma", "title": "Il Telegramma Zimmermann — Il Messico Attacca gli USA?", "year": 1917, "lat": 52.5200, "lng": 13.4050, "category": "storia", "description": "Il 19 gennaio 1917 il ministro degli esteri tedesco Zimmermann invia un telegramma segreto al Messico: se gli USA entrano in guerra, il Messico deve attaccarli in cambio di Texas, New Mexico e Arizona. I britannici intercettano e decodificano il messaggio. Pubblicato dai giornali americani in marzo, scatena l'indignazione che spinge il Congresso a dichiarare guerra alla Germania.", "wikipediaSlug": "Zimmermann_Telegram", "isCosmic": false },
  { "id": "nov-rivoluzione-ottobre", "title": "La Rivoluzione d'Ottobre — I Bolscevichi Prendono il Potere", "year": 1917, "lat": 59.9445, "lng": 30.3195, "category": "storia", "description": "Il 7 novembre 1917 (25 ottobre giuliano) i Bolscevichi di Lenin assaltano il Palazzo d'Inverno a Pietrogrado. In poche ore Lenin proclama il potere dei Soviet. La rivoluzione è quasi incruenta a Pietrogrado ma scatena una guerra civile devastante (1918-1921) e trasforma il mondo per 70 anni. 'Dieci giorni che sconvolsero il mondo' è il titolo del reportage di John Reed, testimone oculare.", "wikipediaSlug": "October_Revolution", "isCosmic": false },
  { "id": "nov-caporetto-disfatta", "title": "Caporetto — La Grande Disfatta Italiana", "year": 1917, "lat": 46.1650, "lng": 13.5820, "category": "storia", "description": "Il 24 ottobre 1917 l'esercito austro-tedesco sfonda le linee italiane a Caporetto con gas, fuoco concentrato e tattiche di infiltrazione: 10.000 italiani morti, 265.000 prigionieri, 350.000 sbandati. La disfatta entra nel lessico italiano come sinonimo di catastrofe. Il generale Cadorna viene sostituito da Diaz. L'esercito si riorganizza sul Piave e resiste fino alla vittoria finale di Vittorio Veneto.", "wikipediaSlug": "Battle_of_Caporetto", "isCosmic": false },
  { "id": "nov-balfour-dichiarazione", "title": "La Dichiarazione Balfour — Promessa di una Patria Ebraica", "year": 1917, "lat": 51.5074, "lng": -0.1278, "category": "storia", "description": "Il 2 novembre 1917 il ministro degli esteri britannico Balfour scrive al leader sionista Lord Rothschild: il governo britannico 'guarda con favore alla creazione di un Focolare Nazionale per il popolo ebraico in Palestina'. Una lettera di 67 parole che cambierà il Medio Oriente per sempre. La Dichiarazione Balfour è all'origine del conflitto arabo-israeliano del XX e XXI secolo.", "wikipediaSlug": "Balfour_Declaration", "isCosmic": false },
  { "id": "nov-tank-cambrai", "title": "Cambrai — L'Era del Carro Armato Inizia", "year": 1917, "lat": 50.1765, "lng": 3.2352, "category": "storia", "description": "Il 20 novembre 1917 i britannici impiegano per la prima volta 476 carri armati Mark IV in massa coordinata a Cambrai: sfondano la Linea Hindenburg di 10 km in un giorno — più di quanto si fosse guadagnato in mesi a Passchendaele. Il successo iniziale non è sfruttato, ma Cambrai mostra il futuro della guerra mobile che dominerà la Seconda Guerra Mondiale.", "wikipediaSlug": "Battle_of_Cambrai_(1917)", "isCosmic": false },
  { "id": "nov-brest-litovsk", "title": "La Pace di Brest-Litovsk — La Russia Esce dalla Guerra", "year": 1918, "lat": 52.0976, "lng": 23.7340, "category": "storia", "description": "Il 3 marzo 1918 la Russia bolscevica firma la pace di Brest-Litovsk: cede Polonia, Finlandia, Paesi Baltici, Ucraina — un terzo del territorio russo europeo. Lenin accetta condizioni umilianti per sopravvivere. Con la Russia fuori, la Germania sposta divisioni a ovest per l'offensiva finale — che fallisce. Il trattato è annullato dall'armistizio tedesco di novembre 1918.", "wikipediaSlug": "Treaty_of_Brest-Litovsk", "isCosmic": false },
  { "id": "nov-offensiva-primavera", "title": "L'Offensiva di Primavera Tedesca — L'Ultima Carta", "year": 1918, "lat": 49.8941, "lng": 3.2881, "category": "storia", "description": "Il 21 marzo 1918 Ludendorff lancia l'Operazione Michael: tattiche di infiltrazione (sturmtruppen), bombe a gas, attacchi su punti deboli. I tedeschi avanzano 60 km — il massimo avanzamento sul fronte occidentale in anni. Ma le riserve americane arrivano in massa, la logistica tedesca si esaurisce. A luglio inizia la controffensiva alleata che porterà all'armistizio di novembre.", "wikipediaSlug": "Spring_Offensive", "isCosmic": false },
  { "id": "nov-influenza-spagnola", "title": "L'Influenza Spagnola — La Pandemia che Uccide Più della Guerra", "year": 1918, "lat": 40.4168, "lng": -3.7038, "category": "storia", "description": "Tra il 1918 e il 1920 l'influenza 'spagnola' (H1N1) uccide tra 50 e 100 milioni di persone — più di quante siano morte in quattro anni di guerra. Il virus colpisce soprattutto i giovani adulti tra 20 e 40 anni. Si diffonde rapidamente tra i soldati nei campi militari sovraffollati. Viene chiamata 'spagnola' solo perché la Spagna — paese neutrale — non censurava le notizie sulla malattia.", "wikipediaSlug": "Spanish_flu", "isCosmic": false },
  { "id": "nov-vittorio-veneto", "title": "Vittorio Veneto — L'Italia Vince la Grande Guerra", "year": 1918, "lat": 45.9849, "lng": 12.3014, "category": "storia", "description": "Dal 24 ottobre al 4 novembre 1918 l'esercito italiano sfonda le linee austro-ungariche a Vittorio Veneto: 300.000 prigionieri, disfatta totale. Il 4 novembre l'Austria firma l'armistizio. L'Italia ha perso 650.000 soldati in quattro anni. Ma la 'vittoria mutilata' — Dalmazia non assegnata nonostante le promesse — alimenterà il risentimento che porta al fascismo e a Mussolini.", "wikipediaSlug": "Battle_of_Vittorio_Veneto", "isCosmic": false },
  { "id": "nov-armistizio-11-novembre", "title": "L'Armistizio dell'11 Novembre — La Grande Guerra Finisce", "year": 1918, "lat": 49.4182, "lng": 2.8325, "category": "storia", "description": "Alle 11:00 dell'11 novembre 1918 le armi tacciono sul fronte occidentale: nella foresta di Compiègne la Germania firma l'armistizio. Dopo 4 anni e 3 mesi la Prima Guerra Mondiale è finita. Il bilancio: 17 milioni di morti militari e civili, 4 imperi dissolti (Germania, Austria-Ungheria, Ottomano, Russo), la mappa dell'Europa ridisegnata. Nasce il 'Secolo Breve'.", "wikipediaSlug": "Armistice_of_11_November_1918", "isCosmic": false },
  { "id": "nov-versailles-trattato", "title": "Il Trattato di Versailles — La Pace che Prepara la Prossima Guerra", "year": 1919, "lat": 48.8049, "lng": 2.1204, "category": "storia", "description": "Il 28 giugno 1919 nella Sala degli Specchi di Versailles viene firmato il trattato con la Germania: perde il 13% del territorio, tutte le colonie, deve pagare 132 miliardi di marchi oro di riparazioni. L'Articolo 231 la dichiara colpevole della guerra. Keynes, consulente britannico, si dimette definendo il trattato economicamente insostenibile — profeticamente.", "wikipediaSlug": "Treaty_of_Versailles", "isCosmic": false },
  { "id": "nov-societa-nazioni", "title": "La Società delle Nazioni — Il Sogno di Wilson", "year": 1920, "lat": 46.2044, "lng": 6.1432, "category": "storia", "description": "Il 10 gennaio 1920 entra in vigore la Società delle Nazioni — primo tentativo di organizzazione internazionale permanente per la pace, ispirata ai 14 Punti di Woodrow Wilson. L'ironia: il Senato USA rifiuta di ratificare e gli USA non entrano mai. Senza strumenti coercitivi, la Società è impotente davanti alle aggressioni degli anni '30. Sopravvive fino al 1946, sostituita dall'ONU.", "wikipediaSlug": "League_of_Nations", "isCosmic": false },
  { "id": "nov-weimar-repubblica", "title": "La Repubblica di Weimar — La Democrazia Fragile", "year": 1919, "lat": 50.9796, "lng": 11.3293, "category": "storia", "description": "Il 31 luglio 1919 a Weimar viene adottata la nuova costituzione tedesca: repubblica parlamentare con diritti fondamentali, suffragio universale, proporzionale. La repubblica nasce nel caos: rivoluzione spartachista, iperinflazione, putsch di destra e sinistra. Nata 'sconfitta' dalla firma dell'armistizio, sopporta il peso delle riparazioni. Muore il 30 gennaio 1933 quando Hitler diventa cancelliere.", "wikipediaSlug": "Weimar_Republic", "isCosmic": false },
  { "id": "nov-mussolini-marcia-roma", "title": "La Marcia su Roma — Il Fascismo Prende il Potere", "year": 1922, "lat": 41.9028, "lng": 12.4964, "category": "storia", "description": "Il 28 ottobre 1922 le squadre fasciste convergono su Roma. Il re Vittorio Emanuele III, invece di dichiarare lo stato d'assedio, invita Benito Mussolini a formare il governo. Mussolini arriva in treno da Milano. In pochi anni smantella il parlamento e instaura la dittatura. La Marcia su Roma diventa il modello che ispirerà Hitler e i movimenti fascisti europei.", "wikipediaSlug": "March_on_Rome", "isCosmic": false },
  { "id": "nov-turchia-ataturk", "title": "Mustafa Kemal Atatürk — La Turchia Moderna Nasce", "year": 1923, "lat": 39.9334, "lng": 32.8597, "category": "storia", "description": "Il 29 ottobre 1923 Mustafa Kemal proclama la Repubblica di Turchia ad Ankara — ponendo fine al Sultanato Ottomano. Atatürk modernizza radicalmente il paese: laicismo, alfabeto latino, calendario gregoriano, abolizione del califfato, diritto di voto alle donne (1934). La Turchia si trasforma in 15 anni in uno stato laico e moderno — modello unico nel mondo musulmano.", "wikipediaSlug": "Mustafa_Kemal_Atatürk", "isCosmic": false },
  { "id": "nov-urss-fondazione", "title": "L'URSS — La Prima Nazione Comunista", "year": 1922, "lat": 55.7558, "lng": 37.6173, "category": "storia", "description": "Il 30 dicembre 1922 Russia, Ucraina, Bielorussia e Transcaucasia si uniscono nella USSR — il primo stato comunista del mondo. Lenin è gravemente malato; la lotta per la successione tra Stalin e Trotsky è già in corso. L'URSS crescerà fino a 15 repubbliche, diventerà superpotenza atomica e si dissolverà nel 1991 — dopo 69 anni di esistenza.", "wikipediaSlug": "Soviet_Union", "isCosmic": false },
  { "id": "nov-putsch-birra-hitler", "title": "Il Putsch della Birreria — Hitler in Prigione, Poi al Potere", "year": 1923, "lat": 48.1351, "lng": 11.5820, "category": "storia", "description": "L'8 novembre 1923 Hitler e il generale Ludendorff tentano a Monaco un colpo di stato ispirato alla Marcia su Roma: fallisce, 16 nazisti vengono uccisi dalla polizia, Hitler è arrestato. Condanna: 5 anni di carcere (ne fa 9 mesi). In prigione scrive Mein Kampf. Il fallimento insegna a Hitler che il potere si conquista con le elezioni — non con la violenza di piazza.", "wikipediaSlug": "Beer_Hall_Putsch", "isCosmic": false },
  { "id": "nov-iperinflazione-weimar", "title": "L'Iperinflazione Tedesca — 1 Dollaro = 4,2 Miliardi di Marchi", "year": 1923, "lat": 52.5200, "lng": 13.4050, "category": "storia", "description": "Nel 1923 la Germania vive l'iperinflazione più famosa della storia: a novembre il tasso di cambio è 4.200 miliardi di marchi per 1 dollaro. La gente porta carriole di banconote per comprare il pane; i soldi vengono bruciati come combustibile. L'iperinflazione distrugge i risparmi della classe media tedesca — alimentando il risentimento che porterà al nazismo.", "wikipediaSlug": "Hyperinflation_in_the_Weimar_Republic", "isCosmic": false },
  { "id": "nov-lindbergh-atlantico", "title": "Lindbergh Attraversa l'Atlantico — 33 Ore, da Solo", "year": 1927, "lat": 48.8566, "lng": 2.3522, "category": "storia", "description": "Il 20-21 maggio 1927 Charles Lindbergh vola da New York a Parigi senza scalo sul monoplano Spirit of St. Louis: 5.810 km in 33 ore e 30 minuti. Primo volo transatlantico solitario senza scalo. All'atterraggio al Le Bourget lo attendono 100.000 persone in delirio. Lindbergh diventa la prima celebrità mediatica dell'era moderna e apre l'era del trasporto aereo commerciale.", "wikipediaSlug": "Transatlantic_flight_of_Charles_Lindbergh", "isCosmic": false },
  { "id": "nov-penicillina-fleming", "title": "La Penicillina — Alexander Fleming Salva Miliardi di Vite", "year": 1928, "lat": 51.5074, "lng": -0.1278, "category": "scienza", "description": "Il 28 settembre 1928 Alexander Fleming nota che una muffa (Penicillium notatum) ha contaminato una piastra di stafilococchi — e li ha uccisi. Scopre la penicillina. Florey e Chain la purificano negli anni '40. La penicillina diventa il primo antibiotico: salva decine di milioni di vite, trasforma la chirurgia, rende curabili infezioni prima mortali. Nobel per Fleming, Florey e Chain nel 1945.", "wikipediaSlug": "Penicillin", "isCosmic": false },
  { "id": "nov-wall-street-crollo", "title": "Il Crollo di Wall Street — Inizio della Grande Depressione", "year": 1929, "lat": 40.7069, "lng": -74.0089, "category": "storia", "description": "Il 24 ottobre 1929 ('Giovedì Nero') e il 29 ottobre ('Martedì Nero') le borse di New York crollano: 30 miliardi di dollari di capitalizzazione evaporati in una settimana. Falliscono 9.000 banche americane, 25% di disoccupazione, il PIL USA dimezza. La Grande Depressione si diffonde globalmente e dura fino alla Seconda Guerra Mondiale.", "wikipediaSlug": "Wall_Street_Crash_of_1929", "isCosmic": false },
  { "id": "nov-gandhi-sale", "title": "La Marcia del Sale — La Resistenza Non Violenta di Gandhi", "year": 1930, "lat": 21.2154, "lng": 72.8301, "category": "storia", "description": "Il 12 marzo 1930 Gandhi parte da Sabarmati con 78 seguaci per una marcia di 388 km verso Dandi, sul mare. Il 5 aprile raccoglie simbolicamente del sale dall'oceano — sfidando il monopolio coloniale britannico. La Marcia del Sale è il più celebre atto di disobbedienza civile del XX secolo: 60.000 arrestati, l'opinione mondiale si sposta contro il dominio britannico sull'India.", "wikipediaSlug": "Salt_March", "isCosmic": false },
  { "id": "nov-giappone-manciuria", "title": "L'Invasione della Manciuria — Il Primo Atto del Conflitto Mondiale", "year": 1931, "lat": 41.8057, "lng": 123.4315, "category": "storia", "description": "Il 18 settembre 1931 l'Esercito Kwantung giapponese organizza l'incidente di Mukden — fa esplodere un tratto della ferrovia e incolpa i cinesi — per giustificare l'invasione della Manciuria. In tre mesi controlla l'intera regione e crea lo stato fantoccio del Manciukuò. La Società delle Nazioni condanna il Giappone ma non agisce: lezione imparata da Hitler e Mussolini.", "wikipediaSlug": "Japanese_invasion_of_Manchuria", "isCosmic": false },
  { "id": "nov-hitler-cancelliere", "title": "Hitler Cancelliere — Il 30 Gennaio 1933", "year": 1933, "lat": 52.5200, "lng": 13.4050, "category": "storia", "description": "Il 30 gennaio 1933 il presidente Hindenburg nomina Hitler cancelliere della Germania — credendo di poterlo controllare. In sei mesi Hitler smantella la democrazia: incendio del Reichstag (27 febbraio), legge dei pieni poteri (23 marzo), proibizione di tutti i partiti (luglio), morte di Hindenburg e assunzione della presidenza (agosto 1934). La Repubblica di Weimar è finita; inizia il Terzo Reich.", "wikipediaSlug": "Adolf_Hitler's_rise_to_power", "isCosmic": false },
  { "id": "nov-dachau-primo-campo", "title": "Dachau — Il Primo Campo di Concentramento Nazista", "year": 1933, "lat": 48.2683, "lng": 11.4685, "category": "storia", "description": "Il 22 marzo 1933 Heinrich Himmler apre il campo di concentramento di Dachau — 53 giorni dopo che Hitler è diventato cancelliere. Inizialmente per oppositori politici (comunisti, socialdemocratici, sindacalisti). Diventa il 'modello' per tutti gli altri campi del sistema concentrazionario. Vi moriranno oltre 41.000 persone. Viene liberato dalle truppe americane il 29 aprile 1945.", "wikipediaSlug": "Dachau_concentration_camp", "isCosmic": false },
  { "id": "nov-new-deal-usa", "title": "Il New Deal — Roosevelt Salva il Capitalismo Americano", "year": 1933, "lat": 38.8951, "lng": -77.0364, "category": "storia", "description": "Nel marzo 1933 il presidente Franklin D. Roosevelt lancia il New Deal: 100 giorni di leggi che rivoluzionano il rapporto stato-economia negli USA. Works Progress Administration, Social Security Act, regolamentazione bancaria. Lo stato federale crea lavoro, protegge gli agricoltori, garantisce pensioni. Il New Deal crea il welfare state americano e salva la democrazia nel momento più buio della Depressione.", "wikipediaSlug": "New_Deal", "isCosmic": false },
  { "id": "nov-leggi-norimberga", "title": "Le Leggi di Norimberga — Il Razzismo Diventa Legge", "year": 1935, "lat": 49.4521, "lng": 11.0767, "category": "storia", "description": "Il 15 settembre 1935 al Congresso del Partito Nazista a Norimberga vengono approvate le Leggi per la protezione del sangue tedesco: gli ebrei perdono la cittadinanza, i matrimoni misti sono vietati. Le Leggi di Norimberga formalizzano la persecuzione antisemita come politica di stato e sono la prima tappa giuridica verso la Shoah.", "wikipediaSlug": "Nuremberg_Laws", "isCosmic": false },
  { "id": "nov-guerra-civile-spagna", "title": "La Guerra Civile Spagnola — Il Laboratorio della Seconda Guerra", "year": 1936, "lat": 40.4168, "lng": -3.7038, "category": "storia", "description": "Il 17 luglio 1936 il generale Francisco Franco guida un golpe contro la Repubblica spagnola: inizia la guerra civile (1936-1939). L'Italia e la Germania supportano Franco con truppe e aviazione; l'URSS supporta la Repubblica. Le Brigate Internazionali — volontari da tutto il mondo — combattono per la Repubblica. La guerra diventa il banco di prova delle tattiche e dell'aviazione della Seconda Guerra Mondiale.", "wikipediaSlug": "Spanish_Civil_War", "isCosmic": false },
  { "id": "nov-guernica-bombardamento", "title": "Guernica — Il Bombardamento della Città Indifesa", "year": 1937, "lat": 43.3127, "lng": -2.6817, "category": "arte", "description": "Il 26 aprile 1937 l'aviazione tedesca (Legione Condor) e italiana bombardano Guernica, città basca indifesa. Muoiono tra 150 e 1.600 civili. Pablo Picasso, incaricato di dipingere un murale per l'Esposizione Universale di Parigi, trasforma l'evento in Guernica — opera di 3,49 × 7,76 metri, il più famoso atto d'accusa contro la guerra del XX secolo.", "wikipediaSlug": "Bombing_of_Guernica", "isCosmic": false },
  { "id": "nov-nanchino-massacro", "title": "Il Massacro di Nanchino — L'Olocausto dell'Asia", "year": 1937, "lat": 32.0603, "lng": 118.7969, "category": "storia", "description": "Dal dicembre 1937 al febbraio 1938 l'esercito giapponese occupa Nanchino e massacra la popolazione civile: stime tra 200.000 e 300.000 morti, violenze di massa sistematiche. Il 'Massacro di Nanchino' è uno dei peggiori crimini di guerra della storia. Il Giappone ancora oggi non lo riconosce pienamente — fonte di tensione diplomatica permanente con la Cina.", "wikipediaSlug": "Nanjing_massacre", "isCosmic": false },
  { "id": "nov-anschluss-austria", "title": "L'Anschluss — La Germania Ingloba l'Austria", "year": 1938, "lat": 48.2082, "lng": 16.3738, "category": "storia", "description": "Il 12 marzo 1938 le truppe tedesche entrano in Austria accolte da folle entusiaste. L'Austria cessa di esistere come stato e diventa l'Ostmark del Reich. La Società delle Nazioni non fa nulla. L'Anschluss incorpora 7 milioni di tedeschi d'Austria nel Reich e sposta la frontiera tedesca fino all'Italia e alla Cecoslovacchia.", "wikipediaSlug": "Anschluss", "isCosmic": false },
  { "id": "nov-monaco-accordo", "title": "Monaco 1938 — L'Appeasement e il Tradimento della Cecoslovacchia", "year": 1938, "lat": 48.1351, "lng": 11.5820, "category": "storia", "description": "Il 29 settembre 1938 Chamberlain, Daladier, Hitler e Mussolini firmano l'accordo di Monaco: i Sudeti vengono ceduti alla Germania senza che la Cecoslovacchia sia invitata. Chamberlain torna a Londra con il celebre foglio: 'Pace per il nostro tempo'. In sei mesi Hitler occupa tutta la Cecoslovacchia. Monaco diventa sinonimo di capitolazione davanti a un aggressore.", "wikipediaSlug": "Munich_Agreement", "isCosmic": false },
  { "id": "nov-kristallnacht", "title": "La Notte dei Cristalli — Il Pogrom Nazista", "year": 1938, "lat": 52.5200, "lng": 13.4050, "category": "storia", "description": "Il 9-10 novembre 1938 le SA e le SS organizzano un pogrom sistematico in tutta la Germania: 7.500 negozi ebraici distrutti, 1.400 sinagoghe incendiate, 91 ebrei uccisi, 30.000 arrestati. La 'Notte dei Cristalli' (Kristallnacht) prende il nome dai vetri delle vetrine frantumati. È il segnale che la persecuzione ha abbandonato il campo legale per la violenza fisica di massa.", "wikipediaSlug": "Kristallnacht", "isCosmic": false },
  { "id": "nov-patto-molotov-ribbentrop", "title": "Il Patto Molotov-Ribbentrop — L'Alleanza tra Nemici Mortali", "year": 1939, "lat": 55.7558, "lng": 37.6173, "category": "storia", "description": "Il 23 agosto 1939 Germania e URSS firmano a Mosca un patto di non aggressione con un protocollo segreto: si dividono la Polonia e l'Europa orientale in sfere d'influenza. Il patto libera Hitler dalla guerra su due fronti. Durerà fino al 22 giugno 1941 quando Hitler attacca l'URSS — tradendo il suo stesso accordo.", "wikipediaSlug": "Molotov–Ribbentrop_Pact", "isCosmic": false },
  { "id": "nov-polonia-invasione", "title": "L'Invasione della Polonia — L'Inizio della Seconda Guerra Mondiale", "year": 1939, "lat": 52.2297, "lng": 21.0122, "category": "storia", "description": "Il 1° settembre 1939 la Germania invade la Polonia con la Blitzkrieg. Il 17 settembre anche l'URSS invade da est. Il 27 settembre Varsavia capitola. Francia e Gran Bretagna dichiarano guerra alla Germania il 3 settembre. La Polonia viene invasa, occupata e divisa in due settimane. Inizia la Seconda Guerra Mondiale — il conflitto più distruttivo della storia umana con 70-85 milioni di morti.", "wikipediaSlug": "Invasion_of_Poland", "isCosmic": false },
  { "id": "nov-dunkerque-evacuazione", "title": "Dunkerque — Il Miracolo dell'Evacuazione", "year": 1940, "lat": 51.0343, "lng": 2.3769, "category": "storia", "description": "Tra il 26 maggio e il 4 giugno 1940 le truppe britanniche e francesi intrappolate a Dunkerque vengono evacuate via mare: 338.000 soldati salvati da 861 imbarcazioni civili e militari — pescherecci, yacht, traghetti. Churchill presenta Dunkerque come un 'miracolo': tecnicamente una sconfitta catastrofica, psicologicamente un atto di resistenza eroica.", "wikipediaSlug": "Dunkirk_evacuation", "isCosmic": false },
  { "id": "nov-battaglia-inghilterra", "title": "La Battaglia d'Inghilterra — La RAF Ferma la Luftwaffe", "year": 1940, "lat": 51.5074, "lng": -0.1278, "category": "storia", "description": "Da luglio a settembre 1940 la Luftwaffe cerca di ottenere la superiorità aerea sull'Inghilterra per preparare l'invasione. La RAF — con piloti britannici, australiani, polacchi e di altre nazioni — abbatte 1.733 aerei tedeschi. Hitler rinuncia all'invasione. Churchill: 'Mai così tanti devono tanto a così pochi.' Prima sconfitta tedesca della guerra.", "wikipediaSlug": "Battle_of_Britain", "isCosmic": false },
  { "id": "nov-operazione-barbarossa", "title": "Operazione Barbarossa — La Guerra più Grande della Storia", "year": 1941, "lat": 52.0000, "lng": 30.0000, "category": "storia", "description": "Il 22 giugno 1941 la Germania invade l'URSS con 3,8 milioni di soldati, 3.600 carri armati, 2.700 aerei su un fronte di 2.900 km — la più grande operazione militare della storia. In sei mesi la Wehrmacht avanza di 1.000 km, cattura 3 milioni di prigionieri. Ma Mosca non cade: il 5 dicembre 1941 i russi contrattaccano. L'URSS non si arrende.", "wikipediaSlug": "Operation_Barbarossa", "isCosmic": false },
  { "id": "nov-pearl-harbor", "title": "Pearl Harbor — Il Giappone Sveglia il Gigante Dormiente", "year": 1941, "lat": 21.3645, "lng": -157.9762, "category": "storia", "description": "Il 7 dicembre 1941 alle 7:55 del mattino 353 aerei giapponesi attaccano la base navale di Pearl Harbor: affondano 4 corazzate, distruggono 188 aerei, uccidono 2.403 americani. Il giorno dopo gli USA dichiarano guerra al Giappone; la Germania dichiara guerra agli USA. Roosevelt: 'Un giorno che vivrà nell'infamia.' Pearl Harbor unisce l'America in guerra.", "wikipediaSlug": "Attack_on_Pearl_Harbor", "isCosmic": false },
  { "id": "nov-olocausto-wannsee", "title": "La Conferenza di Wannsee — La Shoah Pianificata", "year": 1942, "lat": 52.4381, "lng": 13.1644, "category": "storia", "description": "Il 20 gennaio 1942 nella villa Am Großen Wannsee 15 alti funzionari nazisti si incontrano per 90 minuti: pianificano la 'Soluzione Finale della questione ebraica' — lo sterminio di 11 milioni di ebrei europei. Vengono costruiti i campi di sterminio: Auschwitz-Birkenau, Treblinka, Sobibór, Bełżec, Chełmno, Majdanek. Il protocollo di Wannsee è il documento più agghiacciante della storia moderna.", "wikipediaSlug": "Wannsee_Conference", "isCosmic": false },
  { "id": "nov-stalingrado-battaglia", "title": "Stalingrado — Il Punto di Svolta della Seconda Guerra", "year": 1942, "lat": 48.7080, "lng": 44.5133, "category": "storia", "description": "Dal 23 agosto 1942 al 2 febbraio 1943 la Battaglia di Stalingrado è la più sanguinosa della storia: 2 milioni di vittime totali. I tedeschi combattono casa per casa; l'Operazione Urano russa accerchia la VI Armata del feldmaresciallo Paulus. Paulus si arrende il 2 febbraio 1943 con 91.000 sopravvissuti. Stalingrado segna la svolta: i tedeschi non avanzeranno più.", "wikipediaSlug": "Battle_of_Stalingrad", "isCosmic": false },
  { "id": "nov-el-alamein", "title": "El Alamein — Rommel Fermato nel Deserto", "year": 1942, "lat": 30.8339, "lng": 28.9564, "category": "storia", "description": "Il 23 ottobre 1942 il generale Montgomery lancia la Seconda Battaglia di El Alamein contro l'Afrika Korps di Rommel: dopo 12 giorni il 'Volpe del Deserto' è costretto alla ritirata. El Alamein ferma l'avanzata tedesca verso il Canale di Suez e il petrolio del Medio Oriente. Churchill: 'Non è la fine. Ma è, forse, la fine dell'inizio.'", "wikipediaSlug": "Second_Battle_of_El_Alamein", "isCosmic": false },
  { "id": "nov-sbarco-sicilia", "title": "Lo Sbarco in Sicilia — L'Italia Torna Campo di Battaglia", "year": 1943, "lat": 37.0902, "lng": 14.1789, "category": "storia", "description": "Il 9 luglio 1943 Americani e Britannici sbarcano in Sicilia (Operazione Husky) — il più grande sbarco anfibio fino al D-Day. In 38 giorni la Sicilia è liberata. Il 25 luglio il Gran Consiglio vota la sfiducia a Mussolini: il re lo fa arrestare. L'8 settembre l'armistizio; i tedeschi occupano l'Italia e la guerra sul suolo italiano dura fino al 1945.", "wikipediaSlug": "Allied_invasion_of_Sicily", "isCosmic": false },
  { "id": "nov-d-day-normandia", "title": "Il D-Day — Lo Sbarco in Normandia", "year": 1944, "lat": 49.3683, "lng": -0.5381, "category": "storia", "description": "Il 6 giugno 1944 156.000 soldati alleati sbarcano sulle spiagge della Normandia in 5 settori: Utah, Omaha, Gold, Juno, Sword. Omaha Beach è un massacro: 2.000 morti americani in poche ore. Le teste di ponte tengono. Operazione Overlord è la più grande operazione anfibia della storia. In agosto Parigi è liberata; il 25 agosto De Gaulle sfila sugli Champs-Élysées.", "wikipediaSlug": "Normandy_landings", "isCosmic": false },
  { "id": "nov-parigi-liberata", "title": "La Liberazione di Parigi — De Gaulle sugli Champs-Élysées", "year": 1944, "lat": 48.8566, "lng": 2.3522, "category": "storia", "description": "Il 25 agosto 1944 le truppe francesi e americane liberano Parigi. Il comandante tedesco von Choltitz, invece di obbedire all'ordine di Hitler di distruggere la città, si arrende. De Gaulle sfila il 26 agosto tra 2 milioni di parigini in delirio. Colpi di franco-tiratori non fermano la parata — le immagini girano il mondo e diventano simbolo della liberazione.", "wikipediaSlug": "Liberation_of_Paris", "isCosmic": false },
  { "id": "nov-hiroshima-bomba", "title": "Hiroshima — L'Era Atomica Inizia con una Città Distrutta", "year": 1945, "lat": 34.3955, "lng": 132.4536, "category": "scienza", "description": "Il 6 agosto 1945 alle 8:15 il bombardiere americano Enola Gay sgancia Little Boy su Hiroshima: 12.500 tonnellate di TNT equivalenti, 66.000 morti istantanei, 140.000 entro fine anno per le radiazioni. Il 9 agosto Fat Man su Nagasaki: altri 70.000 morti. Il 15 agosto il Giappone si arrende. L'umanità ha imparato a distruggersi totalmente.", "wikipediaSlug": "Atomic_bombings_of_Hiroshima_and_Nagasaki", "isCosmic": false },
  { "id": "nov-auschwitz-olocausto", "title": "Auschwitz-Birkenau — Il Centro dello Sterminio Nazista", "year": 1942, "lat": 50.0343, "lng": 19.2062, "category": "storia", "description": "Dal 1942 al 1945 il complesso di Auschwitz-Birkenau in Polonia è il più grande centro di sterminio nazista: 1,1 milioni di ebrei uccisi nelle camere a gas, più altri 200.000 tra rom, prigionieri sovietici, disabili. Auschwitz diventa il simbolo dell'Olocausto. Il 27 gennaio 1945 i soldati sovietici liberano il campo trovando 7.000 sopravvissuti. Il 27 gennaio è oggi il Giorno della Memoria.", "wikipediaSlug": "Auschwitz_concentration_camp", "isCosmic": false },
  { "id": "nov-bengala-carestia", "title": "La Carestia del Bengala — 3 Milioni di Morti sotto il Dominio Britannico", "year": 1943, "lat": 22.5726, "lng": 88.3639, "category": "storia", "description": "Nel 1943 il Bengala (India britannica) vive una carestia devastante: tra 2 e 3 milioni di morti. La carestia è aggravata dalle politiche coloniali britanniche che esportano riso nonostante la carenza e dalla priorità militare della guerra. Winston Churchill è criticato per la sua indifferenza alla tragedia. La carestia del Bengala diventa simbolo del fallimento morale del colonialismo.", "wikipediaSlug": "Bengal_famine_of_1943", "isCosmic": false },
  { "id": "nov-radio-televisione-nascita", "title": "La Radio e la Televisione Cambiano il Mondo", "year": 1930, "lat": 51.5074, "lng": -0.1278, "category": "scienza", "description": "Negli anni '30 la radio diventa il mezzo di comunicazione di massa dominante: Franklin D. Roosevelt tiene i suoi 'Fireside Chats', Hitler usa la radio per diffondere la propaganda nazista, la BBC lancia trasmissioni regolari. La televisione fa i primi passi: la BBC inizia trasmissioni regolari nel 1936. La radio e la TV rivoluzionano la politica, la cultura e il modo in cui le notizie raggiungono le persone.", "wikipediaSlug": "Golden_Age_of_Radio", "isCosmic": false },
  { "id": "nov-jazz-anni-20", "title": "Il Jazz — La Musica della Libertà negli Anni Ruggenti", "year": 1920, "lat": 29.9511, "lng": -90.0715, "category": "musica", "description": "Gli anni '20 sono i 'Roaring Twenties' del jazz: Louis Armstrong, Duke Ellington, Bessie Smith. Il jazz nasce a New Orleans (comunità afroamericane) e conquista Chicago, New York e l'Europa. Harlem Renaissance: esplosione culturale della comunità afroamericana. Il jazz è ribellione, libertà, modernità — e la colonna sonora dell'età del proibizionismo e dei cocktail clandestini.", "wikipediaSlug": "Jazz", "isCosmic": false },
  { "id": "nov-hollywood-cinema-sonoro", "title": "Hollywood e il Cinema Sonoro — Il Jazz Singer 1927", "year": 1927, "lat": 34.0928, "lng": -118.3287, "category": "arte", "description": "Il 6 ottobre 1927 esce The Jazz Singer — il primo film sonoro di successo commerciale. In due anni il cinema muto scomparso: Hollywood diventa la capitale del cinema mondiale. Charlie Chaplin, Buster Keaton, Greta Garbo, Mary Pickford. Il cinema diventa il mezzo di intrattenimento e propaganda più potente del XX secolo.", "wikipediaSlug": "The_Jazz_Singer", "isCosmic": false },
  { "id": "nov-einstein-relativita-generale", "title": "Einstein e la Relatività — La Fisica Rivoluzionata", "year": 1915, "lat": 52.5200, "lng": 13.4050, "category": "scienza", "description": "Nel novembre 1915 Albert Einstein presenta la Teoria della Relatività Generale all'Accademia Prussiana delle Scienze: la gravità non è una forza ma una curvatura dello spazio-tempo causata dalla massa. La luce si piega intorno alle stelle. Nel 1919 l'eclissi solare conferma la previsione — Einstein diventa famoso in tutto il mondo. La relatività generale trasforma la cosmologia e la fisica moderna.", "wikipediaSlug": "General_relativity", "isCosmic": false },
  { "id": "nov-meccanica-quantistica", "title": "La Meccanica Quantistica — Il Mondo Microscopico non Obbedisce alla Logica", "year": 1927, "lat": 52.0905, "lng": 5.1222, "category": "scienza", "description": "Nel 1927 al Congresso Solvay di Bruxelles i più grandi fisici del mondo (Bohr, Heisenberg, Schrödinger, Einstein) dibattono la meccanica quantistica: il principio di indeterminazione di Heisenberg, la dualità onda-particella, l'interpretazione di Copenaghen. Einstein non accetta ('Dio non gioca a dadi'). La meccanica quantistica rivoluziona la fisica e porta ai transistor, ai laser, ai computer.", "wikipediaSlug": "Quantum_mechanics", "isCosmic": false },
  { "id": "nov-surrealismo-arte", "title": "Il Surrealismo — Dalí, Magritte e il Sogno come Arte", "year": 1924, "lat": 48.8566, "lng": 2.3522, "category": "arte", "description": "Nel 1924 André Breton pubblica il 'Manifesto del Surrealismo' a Parigi: l'arte deve attingere all'inconscio, al sogno, al caso. Salvador Dalí dipinge orologi molli, René Magritte crea immagini impossibili, Joan Miró inventa un linguaggio poetico. Il surrealismo trasforma l'arte, il cinema, la letteratura e persino la pubblicità del XX secolo.", "wikipediaSlug": "Surrealism", "isCosmic": false },
  { "id": "nov-fascismo-italiano-leggi", "title": "Le Leggi Fascistissime — Mussolini Dictator d'Italia", "year": 1926, "lat": 41.9028, "lng": 12.4964, "category": "storia", "description": "Tra il 1925 e il 1926 Mussolini approva le 'leggi fascistissime': abolizione della libertà di stampa, scioglimento dei partiti politici, poteri straordinari al Duce, podestà al posto dei sindaci eletti. L'Italia diventa una dittatura a tutti gli effetti. La mafia non si sottomette — Mussolini lancia la 'guerra alla mafia' con il prefetto Mori, che arresta migliaia di siciliani senza distinzioni.", "wikipediaSlug": "Fascist_Italy", "isCosmic": false },
  { "id": "nov-frank-biennio-rosso", "title": "Il Biennio Rosso — Rivoluzione Mancata in Italia", "year": 1920, "lat": 45.4654, "lng": 9.1866, "category": "storia", "description": "Nel 1919-1920 il 'Biennio Rosso' scuote l'Italia: scioperi generalizzati, occupazioni delle fabbriche a Torino e Milano, contadini che occupano le terre. I lavoratori issano la bandiera rossa nelle fabbriche FIAT. Il movimento non riesce a trasformarsi in rivoluzione — ma spaventa la borghesia e gli industriali che finanzieranno il fascismo come risposta. Gramsci fonda l'Ordine Nuovo.", "wikipediaSlug": "Biennio_rosso", "isCosmic": false },
  { "id": "nov-cina-lunga-marcia", "title": "La Lunga Marcia — Mao e la Sopravvivenza del Comunismo Cinese", "year": 1934, "lat": 28.2277, "lng": 112.9388, "category": "storia", "description": "Dal 1934 al 1935 l'Esercito Rosso di Mao Zedong compie la Lunga Marcia: 12.500 km attraverso le montagne dello Sichuan e dell'Hunan per sfuggire all'accerchiamento del Kuomintang. Partono in 80.000, arrivano in 8.000. La Lunga Marcia trasforma Mao nel leader indiscusso del Partito Comunista Cinese — che nel 1949 prenderà il potere.", "wikipediaSlug": "Long_March", "isCosmic": false },
  { "id": "nov-etiopia-invasione-italiana", "title": "L'Italia Invade l'Etiopia — L'Impero Fascista d'Africa", "year": 1935, "lat": 9.0244, "lng": 38.7468, "category": "storia", "description": "Il 3 ottobre 1935 l'Italia fascista invade l'Etiopia — l'unico paese africano rimasto indipendente oltre al Liberia. L'imperatore Hailé Selassié chiede aiuto alla Società delle Nazioni; questa impone sanzioni economiche all'Italia — incomplete ed inefficaci. L'Etiopia cade nel 1936. Mussolini proclama l'Impero. Le sanzioni inefficaci dimostrano la debolezza della Società delle Nazioni.", "wikipediaSlug": "Second_Italo-Ethiopian_War", "isCosmic": false },
  { "id": "nov-mccarthy-persecuzioni-anticipate", "title": "L'Età dell'Oro del Jazz e il Proibizionismo Americano", "year": 1920, "lat": 41.8827, "lng": -87.6233, "category": "storia", "description": "Il 16 gennaio 1920 entra in vigore il Proibizionismo negli USA: il 18° Emendamento vieta la produzione e vendita di alcolici. Nasce il mercato nero del liquore gestito dalla criminalità organizzata — Al Capone diventa il gangster più famoso d'America. Il proibizionismo è abrogato nel 1933. Paradossalmente, promuove il jazz (nei locali clandestini) e la cultura degli anni '20.", "wikipediaSlug": "Prohibition_in_the_United_States", "isCosmic": false },
  { "id": "nov-india-gandhi-indipendenza", "title": "Gandhi e la Lotta per l'Indipendenza Indiana", "year": 1920, "lat": 28.6139, "lng": 77.2090, "category": "storia", "description": "Dal 1920 al 1947 Mahatma Gandhi guida il movimento di indipendenza indiana contro il dominio britannico attraverso la non-violenza (ahimsa) e la non-cooperazione civile. Campagne di massa, boicottaggi, digiuni. La Marcia del Sale (1930), il Quit India Movement (1942). Il 15 agosto 1947 l'India ottiene l'indipendenza — Gandhi viene assassinato nel 1948 da un estremista hindu.", "wikipediaSlug": "Indian_independence_movement", "isCosmic": false },
  { "id": "nov-arte-bauhaus", "title": "Il Bauhaus — L'Arte che Cambia il Design Moderno", "year": 1919, "lat": 51.0105, "lng": 11.3279, "category": "arte", "description": "Nel 1919 Walter Gropius fonda il Bauhaus a Weimar (poi Dessau, poi Berlino): scuola rivoluzionaria che fonde arte, artigianato e tecnologia. Paul Klee, Wassily Kandinsky, Marcel Breuer, Ludwig Mies van der Rohe insegnano lì. Il Bauhaus inventa il design moderno: funzionalità + estetica. Chiuso dai nazisti nel 1933, i suoi maestri portano la rivoluzione estetica in tutto il mondo.", "wikipediaSlug": "Bauhaus", "isCosmic": false },
  { "id": "nov-psicanalisi-freud", "title": "Freud e la Psicanalisi — Il Secolo dell'Inconscio", "year": 1920, "lat": 48.2082, "lng": 16.3738, "category": "scienza", "description": "Negli anni '20 la psicanalisi di Sigmund Freud conquista l'Europa: 'Al di là del principio del piacere' (1920), 'L'Io e l'Es' (1923). La scoperta dell'inconscio, dei sogni, delle pulsioni rivoluziona la psicologia, la letteratura, l'arte. Freud nel 1938 fugge da Vienna occupata dai nazisti — muore a Londra nel 1939. La psicanalisi resta il framework dominante della psicologia del XX secolo.", "wikipediaSlug": "Sigmund_Freud", "isCosmic": false },
  { "id": "nov-primo-antibiotico-sulfonamidi", "title": "La Prima Vittoria sulle Infezioni Batteriche — Sulfonamidi 1935", "year": 1935, "lat": 52.5200, "lng": 13.4050, "category": "scienza", "description": "Nel 1932 il chimico tedesco Gerhard Domagk scopre che il Prontosil (colorante azoico) uccide gli streptococchi nei topi. Nel 1935 viene usato clinicamente: primo antibiotico sintetico efficace. Le sulfonamidi salvano milioni di vite nelle prime fasi della Seconda Guerra Mondiale prima che la penicillina diventasse disponibile in grandi quantità. Domagk riceve il Nobel per la medicina nel 1939.", "wikipediaSlug": "Sulfonamide_(medicine)", "isCosmic": false },
  { "id": "nov-onu-fondazione-1945", "title": "La Fondazione dell'ONU — L'Ordine Mondiale del Dopoguerra", "year": 1945, "lat": 37.7749, "lng": -122.4194, "category": "storia", "description": "Il 26 giugno 1945 a San Francisco 50 nazioni firmano la Carta delle Nazioni Unite — l'ONU sostituisce la Società delle Nazioni. A differenza di questa, gli USA sono fondatori e membri permanenti del Consiglio di Sicurezza insieme a UK, Francia, URSS e Cina. L'ONU è il tentativo di costruire un ordine mondiale basato sul diritto internazionale — imperfetto, ma indispensabile.", "wikipediaSlug": "United_Nations", "isCosmic": false },
  { "id": "nov-norimberga-processo", "title": "Il Processo di Norimberga — I Criminali di Guerra Giudicati", "year": 1945, "lat": 49.4521, "lng": 11.0767, "category": "storia", "description": "Dal 20 novembre 1945 al 1° ottobre 1946 i leader nazisti vengono processati a Norimberga dal Tribunale Militare Internazionale: 12 condannati a morte (tra cui Göring, Ribbentrop, Keitel), 3 all'ergastolo, 4 a pene detentive, 3 assolti. Il processo stabilisce il principio che i crimini di guerra e contro l'umanità non possono essere giustificati dagli ordini ricevuti.", "wikipediaSlug": "Nuremberg_trials", "isCosmic": false },
  { "id": "nov-shoah-cifre", "title": "La Shoah — Il Genocidio degli Ebrei d'Europa", "year": 1943, "lat": 50.0341, "lng": 20.0610, "category": "storia", "description": "Tra il 1941 e il 1945 i nazisti sterminano sistematicamente 6 milioni di ebrei europei — i due terzi degli ebrei d'Europa. I campi di sterminio (Vernichtungslager): Auschwitz-Birkenau, Treblinka, Sobibor, Belzec, Chelmno, Majdanek. La Shoah è il crimine più documentato della storia umana. 'Mai più' diventa la promessa dell'umanità — non sempre mantenuta.", "wikipediaSlug": "The_Holocaust", "isCosmic": false },
  { "id": "nov-resistenza-italiana", "title": "La Resistenza Italiana — Partigiani contro i Nazifascisti", "year": 1943, "lat": 45.4654, "lng": 9.1866, "category": "storia", "description": "Dopo l'8 settembre 1943, con l'occupazione tedesca dell'Italia, nasce la Resistenza: 100.000-200.000 partigiani combattono nelle montagne del nord. Brigate Garibaldi (comuniste), Giustizia e Libertà, formazioni cattoliche e monarchiche. Il 25 aprile 1945 (Liberazione) i partigiani insorgono e liberano le città prima dell'arrivo degli Alleati. Mussolini viene catturato e fucilato il 28 aprile.", "wikipediaSlug": "Italian_resistance_movement", "isCosmic": false },
  { "id": "nov-midway-battaglia", "title": "La Battaglia di Midway — Il Punto di Svolta nel Pacifico", "year": 1942, "lat": 28.2072, "lng": -177.3735, "category": "storia", "description": "Dal 4 al 7 giugno 1942 la Marina degli Stati Uniti affonda 4 portaerei giapponesi durante la Battaglia di Midway — in cambio di 1 portaerei americana. Midway è la svolta della guerra nel Pacifico: il Giappone non recupererà mai la superiorità navale persa. L'intelligence americana ha decifrato i codici giapponesi — vantaggio decisivo. Il Giappone è ora sulla difensiva.", "wikipediaSlug": "Battle_of_Midway", "isCosmic": false },
  { "id": "nov-la-passione-di-giovanna-darco", "title": "La Passione di Giovanna d'Arco — Il Capolavoro del Cinema Muto", "year": 1928, "lat": 48.8566, "lng": 2.3522, "category": "arte", "description": "Nel 1928 Carl Theodor Dreyer dirige 'La Passione di Giovanna d'Arco': primo piano dopo primo piano sul viso dell'attrice Renée Falconetti, senza trucco, nelle scene del processo. Considerato uno dei più grandi film della storia del cinema, rappresenta il vertice del cinema muto proprio quando il cinema sonoro sta per soppiantarlo. Il film fu riscoperto integro solo nel 1981 in un ospedale psichiatrico norvegese.", "wikipediaSlug": "The_Passion_of_Joan_of_Arc", "isCosmic": false },
  { "id": "nov-kafka-opere", "title": "Franz Kafka — Il Castello e La Metamorfosi", "year": 1925, "lat": 50.0755, "lng": 14.4378, "category": "arte", "description": "Franz Kafka muore a 40 anni di tubercolosi nel 1924, chiedendo all'amico Max Brod di bruciare i suoi manoscritti. Brod disobbedisce e pubblica Il Processo (1925), Il Castello (1926), America (1927). Kafka diventa il scrittore del '900 che meglio ha descritto l'alienazione, la burocrazia assurda, l'angoscia moderna. 'Kafkiano' entra nel lessico di tutte le lingue del mondo.", "wikipediaSlug": "Franz_Kafka", "isCosmic": false }
];

